/* @lc app=leetcode id=3868 lang=kotlin */ class Solution { fun minCost(nums1: IntArray, nums2: IntArray): Int = nums1.toList().groupingBy { it }.eachCount().let { c1 -> nums2.toList().groupingBy { it }.eachCount().let { c2 -> (c1.keys + c2.keys).let { ks -> if (ks.any { ((c1[it] ?: 0) + (c2[it] ?: 0)) % 2 == 1 }) -1 else ks.sumOf { maxOf(0, (c1[it] ?: 0) - ((c1[it] ?: 0) + (c2[it] ?: 0)) / 2) } } } } }